public enum Error {

    
    
    case Io(message: String)
    
    case Format(message: String)
    
    case Missing(message: String)
    
    case Unsupported(message: String)
    
    case Shader(message: String)
    
    case Metal(message: String)
    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeError: FfiConverterRustBuffer {
    typealias SwiftType = Error

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Error {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Format(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .Missing(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .Unsupported(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Shader(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .Metal(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Error, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Io(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .Format(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .Missing(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .Unsupported(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Shader(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Metal(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))

        
        }
    }
}


